package com.campus.market.order;
import com.campus.market.product.*;
import com.campus.market.auth.SessionService;
import com.campus.market.user.UserResponse;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static com.campus.market.order.OrderModels.*;
@SpringBootTest(properties={"spring.datasource.url=${LESSON69_DB_URL:jdbc:mysql://127.0.0.1:1/disabled}","spring.datasource.username=root","spring.datasource.password=","market.product-cache.enabled=true","spring.data.redis.port=${LESSON67_REDIS_PORT:1}"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
@EnabledIfEnvironmentVariable(named="LESSON69_DB_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/campus_lesson69_verify\\?.*")
class OrderIntegrationTest {
 @Autowired ProductDetailCache cache;
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired OrderService service;@Autowired ProductService products;
 @Autowired ProductRepository repository;@Autowired SessionService sessions;@Autowired PlatformTransactionManager transactions;@Autowired PasswordEncoder encoder;
 final JsonMapper json=JsonMapper.builder().build();String hash,sellerToken,buyerToken,otherToken;long product,seller,buyer,other;
 @BeforeAll void hash(){hash=encoder.encode("Campus2026!");}
 @BeforeEach void fixtures()throws Exception {
  assertTrue(System.getenv("LESSON69_DB_URL").contains("/campus_lesson69_verify?"));
  com.campus.market.support.FinancialFixtureCleanup.clear(jdbc);jdbc.update("DELETE FROM market_orders");jdbc.update("DELETE FROM product_comments");jdbc.update("DELETE FROM product_favorites");jdbc.update("DELETE FROM purchase_intents");jdbc.update("DELETE FROM products");jdbc.update("DELETE FROM login_sessions");jdbc.update("DELETE FROM users");
  seller=user("order_seller");buyer=user("order_buyer");other=user("order_other");
  sellerToken=token(seller,"order_seller");buyerToken=token(buyer,"order_buyer");otherToken=token(other,"order_other");
  product=repository.insert("订单教材","原始描述",3500,seller,null,"BOOK");
 }
 long user(String name){jdbc.update("INSERT INTO users(username,password_hash,nickname) VALUES(?,?,?)",name,hash,name);return jdbc.queryForObject("SELECT id FROM users WHERE username=?",Long.class,name);}
 String token(long id,String username){return "Bearer "+sessions.issueToken(new UserResponse(id,username,username)).accessToken();}
 String uuid(){return UUID.randomUUID().toString();}
 JsonNode check(MockHttpServletRequestBuilder request,int status)throws Exception {var r=mvc.perform(request).andReturn().getResponse();assertEquals(status,r.getStatus(),r.getContentAsString(StandardCharsets.UTF_8));return r.getContentAsByteArray().length==0?null:json.readTree(r.getContentAsString(StandardCharsets.UTF_8));}
 MockHttpServletRequestBuilder create(long id,long version,String key,String auth){var q=post("/api/products/"+id+"/orders").contentType("application/json").content(json.writeValueAsString(Map.of("productVersion",version,"requestId",key)));return auth==null?q:q.header("Authorization",auth);}
 long created()throws Exception{return check(create(product,0,uuid(),buyerToken),201).get("order").get("id").asLong();}
 long version(){return repository.findById(product).orElseThrow().version();}
 long count(){return jdbc.queryForObject("SELECT COUNT(*) FROM market_orders",Long.class);}
 @Test void createReturns201WithSnapshotsAndIncrementsProductVersion()throws Exception{var r=check(create(product,0,uuid(),buyerToken),201);assertFalse(r.get("replayed").asBoolean());var o=r.get("order");assertEquals("PENDING_PAYMENT",o.get("status").asText());assertEquals("订单教材",o.get("productTitleSnapshot").asText());assertEquals(3500,o.get("priceInCentsSnapshot").asLong());assertEquals(buyer,o.get("buyer").get("id").asLong());assertEquals(seller,o.get("seller").get("id").asLong());assertEquals(1,version());}
 @Test void sameRequestReplays200WithoutAnotherOrderOrVersionIncrement()throws Exception{String key=uuid();long id=check(create(product,0,key,buyerToken),201).get("order").get("id").asLong();var r=check(create(product,0,key,buyerToken),200);assertTrue(r.get("replayed").asBoolean());assertEquals(id,r.get("order").get("id").asLong());assertEquals(1,count());assertEquals(1,version());}
 @Test void replayWithChangedPayloadConflicts()throws Exception{String key=uuid();check(create(product,0,key,buyerToken),201);check(create(product,1,key,buyerToken),409);assertEquals(1,count());}
 @Test void requestCannotBeReusedForAnotherProduct()throws Exception{String key=uuid();check(create(product,0,key,buyerToken),201);long second=repository.insert("另一本教材","",5500,seller,null,"BOOK");check(create(second,0,key,buyerToken),409);assertEquals(0,repository.findById(second).orElseThrow().version());}
 @Test void anotherBuyerCannotReserveAnOccupiedProduct()throws Exception{created();check(create(product,1,uuid(),otherToken),409);assertEquals(1,count());}
 @Test void anotherRequestFromSameBuyerCannotCreateASecondActiveOrder()throws Exception{created();check(create(product,1,uuid(),buyerToken),409);assertEquals(1,count());}
 @Test void anonymousAndInvalidSessionsCannotOrder()throws Exception{check(create(product,0,uuid(),null),401);check(create(product,0,uuid(),"Bearer "+"A".repeat(43)),401);assertEquals(0,count());}
 @Test void sellerCannotOrderOwnProduct()throws Exception{check(create(product,0,uuid(),sellerToken),403);assertEquals(0,count());}
 @Test void legacyProductWithoutSellerCannotOrder()throws Exception{jdbc.update("UPDATE products SET seller_id=NULL WHERE id=?",product);check(create(product,0,uuid(),buyerToken),409);}
 @Test void offShelfAndSoldProductsCannotOrder()throws Exception{for(String status:List.of("OFF_SHELF","SOLD")){jdbc.update("UPDATE products SET status=? WHERE id=?",status,product);check(create(product,0,uuid(),buyerToken),409);}assertEquals(0,count());}
 @Test void oldProductVersionCannotOrder()throws Exception{jdbc.update("UPDATE products SET version=1 WHERE id=?",product);check(create(product,0,uuid(),buyerToken),409);assertEquals(0,count());}
 @Test void malformedVersionsAndRequestIdsAreRejected()throws Exception{for(String value:List.of("null","-1","1.5","\"0\"","9007199254740992"))check(post("/api/products/"+product+"/orders").header("Authorization",buyerToken).contentType("application/json").content("{\"productVersion\":"+value+",\"requestId\":\""+uuid()+"\"}"),400);for(String key:List.of("","BAD","A".repeat(36)))check(create(product,0,key,buyerToken),400);assertEquals(0,count());}
 @Test void clientPriceAndBuyerFieldsCannotChangeSnapshots()throws Exception{var r=check(post("/api/products/"+product+"/orders").header("Authorization",buyerToken).contentType("application/json").content("{\"productVersion\":0,\"requestId\":\""+uuid()+"\",\"priceInCents\":1,\"buyerId\":"+other+"}"),201).get("order");assertEquals(3500,r.get("priceInCentsSnapshot").asLong());assertEquals(buyer,r.get("buyer").get("id").asLong());}
 @Test void buyerAndSellerCanReadButThirdPartyCannot()throws Exception{long id=created();check(get("/api/orders/"+id).header("Authorization",buyerToken),200);check(get("/api/orders/"+id).header("Authorization",sellerToken),200);check(get("/api/orders/"+id).header("Authorization",otherToken),404);check(get("/api/orders/"+id),401);}
 @Test void listIsScopedToCurrentParticipantAndRole()throws Exception{created();assertEquals(1,check(get("/api/orders").header("Authorization",buyerToken),200).get("total").asLong());assertEquals(0,check(get("/api/orders?role=SELLER").header("Authorization",buyerToken),200).get("total").asLong());assertEquals(1,check(get("/api/orders?role=SELLER").header("Authorization",sellerToken),200).get("total").asLong());assertEquals(0,check(get("/api/orders").header("Authorization",otherToken),200).get("total").asLong());}
 @Test void listValidatesAndClampsPagination()throws Exception{created();assertEquals(1,check(get("/api/orders?page=999").header("Authorization",buyerToken),200).get("page").asInt());for(String q:List.of("role=ADMIN","page=0","size=21","size=0"))check(get("/api/orders?"+q).header("Authorization",buyerToken),400);}
 @Test void cancellationReleasesReservationAndIncrementsVersion()throws Exception{long id=created();var r=check(post("/api/orders/"+id+"/cancel").header("Authorization",buyerToken),200);assertEquals("CANCELLED",r.get("order").get("status").asText());assertFalse(r.get("order").get("cancelledAt").isNull());assertEquals(2,version());check(create(product,2,uuid(),otherToken),201);assertEquals(2,count());}
 @Test void repeatedCancellationIsIdempotent()throws Exception{long id=created();service.cancel(id,buyerToken);assertTrue(service.cancel(id,buyerToken).replayed());assertEquals(2,version());}
 @Test void sellerAndThirdPartyCannotCancelBuyersOrder()throws Exception{long id=created();check(post("/api/orders/"+id+"/cancel").header("Authorization",sellerToken),404);check(post("/api/orders/"+id+"/cancel").header("Authorization",otherToken),404);assertEquals("PENDING_PAYMENT",service.detail(id,buyerToken).status());}
 @Test void replayAfterCancellationReturnsOriginalCancelledOrder()throws Exception{String key=uuid();long id=service.create(product,new Create(0L,key),buyerToken).order().id();service.cancel(id,buyerToken);var replay=service.create(product,new Create(0L,key),buyerToken);assertTrue(replay.replayed());assertEquals("CANCELLED",replay.order().status());assertEquals(1,count());assertEquals(2,version());}
 @Test void cancelledSnapshotSurvivesLaterProductAndNicknameChanges()throws Exception{long id=created();service.cancel(id,buyerToken);jdbc.update("UPDATE products SET title='更改后的书',price_in_cents=9900 WHERE id=?",product);jdbc.update("UPDATE users SET nickname='修改昵称' WHERE id IN (?,?)",buyer,seller);var o=service.detail(id,buyerToken);assertEquals("订单教材",o.productTitleSnapshot());assertEquals(3500,o.priceInCentsSnapshot());assertEquals("order_buyer",o.buyer().nickname());assertEquals("order_seller",o.seller().nickname());}
 @Test void activeOrderPreventsSellerEditAndStatusChange()throws Exception{created();assertThrows(OrderException.class,()->products.updateProduct(product,new UpdateProductRequest("卖家修改教材","",5800L,null,1L),sellerToken));assertThrows(OrderException.class,()->products.updateStatus(product,new UpdateProductStatusRequest(ProductStatus.OFF_SHELF,1L),sellerToken));assertEquals("订单教材",repository.findById(product).orElseThrow().title());}
 @Test void cancellationAllowsSellerToEditAgain()throws Exception{long id=created();service.cancel(id,buyerToken);assertEquals("恢复修改教材",products.updateProduct(product,new UpdateProductRequest("恢复修改教材","",5800L,null,2L),sellerToken).title());}
 @Test void activeOrderPreventsNewPurchaseIntent()throws Exception{created();check(post("/api/products/"+product+"/purchase-intent").header("Authorization",otherToken).contentType("application/json").content("{\"productVersion\":1}"),409);}
 @Test void stateDoesNotLeakOrderIdToOtherBuyersOrAnonymous()throws Exception{long id=created();assertEquals(id,check(get("/api/products/"+product+"/order-state").header("Authorization",buyerToken),200).get("myOrderId").asLong());assertEquals(id,check(get("/api/products/"+product+"/order-state").header("Authorization",sellerToken),200).get("myOrderId").asLong());for(String auth:List.of("",otherToken)){var q=get("/api/products/"+product+"/order-state");if(!auth.isEmpty())q.header("Authorization",auth);var state=check(q,200);assertFalse(state.get("available").asBoolean());assertTrue(state.get("myOrderId").isNull());}}
 @Test void stateReportsAvailabilityAndSellerCannotBuy()throws Exception{assertTrue(check(get("/api/products/"+product+"/order-state"),200).get("available").asBoolean());assertFalse(check(get("/api/products/"+product+"/order-state").header("Authorization",sellerToken),200).get("available").asBoolean());long id=created();service.cancel(id,buyerToken);assertTrue(check(get("/api/products/"+product+"/order-state").header("Authorization",otherToken),200).get("available").asBoolean());}
 @Test void transactionRollbackRestoresBothOrderAndProductVersion(){var tx=new TransactionTemplate(transactions);tx.executeWithoutResult(state->{service.create(product,new Create(0L,uuid()),buyerToken);state.setRollbackOnly();});assertEquals(0,count());assertEquals(0,version());}
 @Test void cancellationRollbackRetainsTheActiveReservation()throws Exception{long id=created();new TransactionTemplate(transactions).executeWithoutResult(state->{service.cancel(id,buyerToken);state.setRollbackOnly();});assertEquals("PENDING_PAYMENT",service.detail(id,buyerToken).status());assertEquals(1,version());assertThrows(OrderException.class,()->service.create(product,new Create(1L,uuid()),otherToken));}
 @Test void twoBuyersConcurrentlyProduceOnlyOneActiveOrder()throws Exception{var executor=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=executor.submit(()->race(start,buyerToken));var b=executor.submit(()->race(start,otherToken));start.countDown();var codes=new ArrayList<>(List.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(201,409),codes);assertEquals(1,count());assertEquals(1,version());}finally{start.countDown();executor.shutdownNow();}}
 int race(CountDownLatch start,String token)throws Exception{start.await();try{service.create(product,new Create(0L,uuid()),token);return 201;}catch(OrderException expected){return expected.status();}}
 @Test void duplicateConcurrentRequestCreatesOneAndReplaysOne()throws Exception{var executor=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);String key=uuid();try{Callable<Receipt> task=()->{start.await();return service.create(product,new Create(0L,key),buyerToken);};var a=executor.submit(task);var b=executor.submit(task);start.countDown();var one=a.get(5,TimeUnit.SECONDS);var two=b.get(5,TimeUnit.SECONDS);assertEquals(one.order().id(),two.order().id());assertNotEquals(one.replayed(),two.replayed());assertEquals(1,count());}finally{start.countDown();executor.shutdownNow();}}
 @Test void databaseUniqueConstraintStopsDirectDuplicateReservations()throws Exception{created();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO market_orders(product_id,buyer_id,seller_id,request_id,product_title_snapshot,price_in_cents_snapshot,product_version_snapshot,buyer_nickname_snapshot,seller_nickname_snapshot) VALUES(?,?,?,?,?,?,?,?,?)",product,other,seller,uuid(),"绕过业务测试",3500,1,"other","seller"));assertEquals(1,count());}
 @Test void repeatableReadSnapshotCannotHideARecentlyCommittedReservation()throws Exception{var executor=Executors.newSingleThreadExecutor();try{new TransactionTemplate(transactions).executeWithoutResult(state->{jdbc.queryForObject("SELECT COUNT(*) FROM market_orders",Long.class);try{executor.submit(()->service.create(product,new Create(0L,uuid()),buyerToken)).get(5,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}assertThrows(OrderException.class,()->products.updateProduct(product,new UpdateProductRequest("旧快照修改教材","",5000L,null,1L),sellerToken));state.setRollbackOnly();});assertEquals(1,count());}finally{executor.shutdownNow();}}
 @Test void versionCeilingDoesNotCreateAnUncancellableOrder()throws Exception{jdbc.update("UPDATE products SET version=9007199254740990 WHERE id=?",product);check(create(product,9007199254740990L,uuid(),buyerToken),409);assertEquals(0,count());}
 @Test void privateStateAndErrorsUseNoStore()throws Exception{long id=created();var r=mvc.perform(get("/api/orders/"+id).header("Authorization",buyerToken)).andReturn().getResponse();assertEquals("no-store",r.getHeader("Cache-Control"));r=mvc.perform(create(product,1,uuid(),otherToken)).andReturn().getResponse();assertEquals("no-store",r.getHeader("Cache-Control"));}
 @Test void invalidIdsAndMissingOrdersAreRejected()throws Exception{check(get("/api/orders/0").header("Authorization",buyerToken),400);check(get("/api/orders/9007199254740991").header("Authorization",buyerToken),404);check(create(9007199254740991L,0,uuid(),buyerToken),404);}
 @Test void reservationAndCancellationEvictTheCorrectCachedVersions()throws Exception{products.getProduct(product,null);assertTrue(cache.read(product,0).isPresent());long id=created();assertTrue(cache.read(product,0).isEmpty());assertEquals(1,products.getProduct(product,null).version());assertTrue(cache.read(product,1).isPresent());service.cancel(id,buyerToken);assertTrue(cache.read(product,1).isEmpty());assertEquals(2,products.getProduct(product,null).version());}
 @Test void rolledBackReservationKeepsTheOriginalPublicCache(){products.getProduct(product,null);assertTrue(cache.read(product,0).isPresent());new TransactionTemplate(transactions).executeWithoutResult(state->{service.create(product,new Create(0L,uuid()),buyerToken);state.setRollbackOnly();});assertTrue(cache.read(product,0).isPresent());assertEquals(0,count());}
 @Test void activeOrderBlocksAcceptanceOfAnEarlierPendingIntent()throws Exception{long intent=check(post("/api/products/"+product+"/purchase-intent").header("Authorization",otherToken).contentType("application/json").content("{\"productVersion\":0}"),201).get("intent").get("id").asLong();created();check(post("/api/purchase-intents/"+intent+"/accept").header("Authorization",sellerToken),409);}
 @Test void sameRequestOnTwoProductsCannotCommitTwoOrders()throws Exception{long second=repository.insert("另一本教材","",6500,seller,null,"BOOK");var executor=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);String key=uuid();try{var a=executor.submit(()->raceProduct(start,product,key));var b=executor.submit(()->raceProduct(start,second,key));start.countDown();var codes=new ArrayList<>(List.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(201,409),codes);assertEquals(1,count());assertEquals(1,version()+repository.findById(second).orElseThrow().version());}finally{start.countDown();executor.shutdownNow();}}
 int raceProduct(CountDownLatch start,long id,String key)throws Exception{start.await();try{service.create(id,new Create(0L,key),buyerToken);return 201;}catch(OrderException expected){return expected.status();}}

}
